import hashlib, os, stat

root = 'data'
pattern = b'invoice'
keep = len(pattern) - 1
chunk_size = 8 * 1024 * 1024

def scan(path):
    h = hashlib.sha256()
    matches = 0
    tail = b''
    line_has = False
    with open(path, 'rb') as f:
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            h.update(chunk)
            data = tail + chunk
            base = len(tail)
            parts = data.split(b'\n')
            if len(parts) == 1:
                if not line_has:
                    start = 0
                    while True:
                        i = parts[0].find(pattern, start)
                        if i < 0:
                            break
                        if i + len(pattern) > base:
                            line_has = True
                            break
                        start = i + 1
                if line_has:
                    tail = b''
                else:
                    tail = data[-keep:] if keep else b''
                if line_has:
                    tail = data[-keep:] if keep else b''
            else:
                first = parts[0]
                if not line_has:
                    start = 0
                    while True:
                        i = first.find(pattern, start)
                        if i < 0:
                            break
                        if i + len(pattern) > base:
                            line_has = True
                            break
                        start = i + 1
                if line_has:
                    matches += 1
                for p in parts[1:-1]:
                    if pattern in p:
                        matches += 1
                last = parts[-1]
                line_has = pattern in last
                tail = last[-keep:] if keep else b''
        if line_has:
            matches += 1
    return h.hexdigest(), matches

files = []
for dirpath, dirnames, filenames in os.walk(root, topdown=True, followlinks=False):
    for name in filenames:
        p = os.path.join(dirpath, name)
        st = os.lstat(p)
        if stat.S_ISREG(st.st_mode):
            rel = os.path.relpath(p, root)
            files.append((rel.encode('utf-8', 'surrogateescape'), p, st.st_size))
files.sort(key=lambda x: x[0])

rows = []
total_matches = 0
for rel_b, p, size in files:
    rel = rel_b.decode('utf-8', 'surrogateescape')
    try:
        digest, matches = scan(p)
        value = digest[:12]
        total_matches += matches
    except OSError:
        value = 'unreadable'
    rows.append(f'{rel} | {size} | {value}')

with open('INVENTORY.md', 'w', encoding='utf-8', newline='\n') as out:
    out.write('\n'.join(rows))
    out.write(f'\ninvoice_lines: {total_matches}\n')

print('\n'.join(rows))
print(f'invoice_lines: {total_matches}')
